fn lamp(y: i32, state: i32) {
    let mut col: i32 = 0xaa7700;
    if state == 1 {
        col = 0x22bb44;
    } else if state == 2 {
        col = 0xbb2222;
    }
    host::display::fill_rect(48, y, 24, 24, col);
}

fn frame(t: i32) {
    host::display::clear(0x0b0d11);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::net::open(0));
        host::display::state_set(2, host::http::get("https://example.com/", 20));
        host::mp::auto(2);
        host::display::state_set(0, 1);
    }
    host::display::draw_string(140, 30, "BRIDGE CHECK", 0xffffff, 3);
    let mut green: i32 = 0;

    let nh: i32 = host::display::state_get(1);
    let mut nstate: i32 = 2;
    if nh >= 0 {
        let s: i32 = host::net::status(nh);
        if s == 1 {
            nstate = 1;
        } else if s == 0 {
            nstate = 0;
        }
    }
    lamp(110, nstate);
    host::display::draw_string(96, 116, "NET SOCKET", 0x8899aa, 2);
    if nstate == 1 {
        green = green + 1;
    }

    let hh: i32 = host::display::state_get(2);
    let mut hstate: i32 = 0;
    if hh < 0 {
        hstate = 2;
    } else {
        let r: i32 = host::http::ready(hh);
        if r == 1 {
            hstate = 1;
        } else if r < 0 {
            hstate = 2;
        }
    }
    lamp(190, hstate);
    host::display::draw_string(96, 196, "HTTP FETCH", 0x8899aa, 2);
    if hstate == 1 {
        host::display::draw_number(300, 196, host::http::status(hh), 0x66ddff, 2);
        green = green + 1;
    }

    let mut mstate: i32 = 0;
    if host::mp::connected() == 1 {
        mstate = 1;
    }
    lamp(270, mstate);
    host::display::draw_string(96, 276, "MULTIPLAYER", 0x8899aa, 2);
    if mstate == 1 {
        host::display::draw_number(300, 276, host::mp::peer_count(), 0x66ddff, 2);
        green = green + 1;
    }

    let mut istate: i32 = 2;
    if host::agent::viewer_has_identity() == 1 {
        istate = 1;
    }
    lamp(350, istate);
    host::display::draw_string(96, 356, "IDENTITY", 0x8899aa, 2);
    if istate == 1 {
        green = green + 1;
    }

    host::display::draw_string(48, 440, "SYSTEMS GREEN", 0x556677, 1);
    host::display::draw_number(170, 434, green, 0xffffff, 2);
    host::display::draw_string(200, 440, "OF 4", 0x556677, 1);
    host::display::present();
}
